ARKS, r2i.RECIEVED_QTY, r2i.REQUIRED_QTY, r2i.RECEIVED_SKUS, NULLIF(LOWER(TRIM(spf.ITEM_SKUCODE)), \'null\') AS ITEM_SKUCODE, NULLIF(LOWER(TRIM(spf.SALE_ORDER_CODE)), \'null\') AS SALE_ORDER_CODE, r2i.REQUIRED_SKUS, r2i.ITEM_COUNT, r2i.PUTAWAY_NUMBER, NULLIF(LOWER(TRIM(spf.putaway_code)), \'null\') AS putaway_code, NULLIF(LOWER(TRIM(spf.QC_COMMENT)), \'null\') AS QC_COMMENT, spf.id as spf_id, COALESCE( TRY_TO_DATE(TRIM(spf.MONTH), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'MON-YY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'MM-YYYY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'MON-YYYY\') ) AS QCd_month, CASE WHEN UPPER(TRIM(spf.DONE_BY)) IN (\'PRADEEP\', \'P\') THEN \'PRADEEP\' WHEN UPPER(TRIM(spf.DONE_BY)) IN (\'BAJARANGI\', \'B\') THEN \'BAJARANGI\' WHEN UPPER(TRIM(spf.DONE_BY)) IN (\'RAMYA\', \'R\') THEN \'RAMYA\' WHEN UPPER(REPLACE(TRIM(spf.DONE_BY), \'’\', \'\')) IN (\'CHANDAN\', \'C\') THEN \'CHANDAN\' WHEN UPPER(REPLACE(TRIM(spf.DONE_BY), \'✓\', \'\')) IN (\'DHYAN\', \'D\',\'DHYAN\', \'DHYNA\', \'DHAYN\',\'DHYA\') THEN \'DHYAN\' ELSE NULL END AS Claims_agent_Name, spf.TICKET_RAISED_BY as SPF_ticket_raised_by, TRY_TO_NUMBER(TRIM(spf.TICKET_NUMBER)) AS TICKET_NUMBER, NULLIF(LOWER(TRIM(spf.TICKET_STATUS)), \'null\') AS TICKET_STATUS, NULLIF(LOWER(TRIM(spf.REJECTION_REASON)), \'null\') AS REJECTION_REASON, COALESCE( TRY_TO_TIMESTAMP(spf.ticket_raised_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(spf.ticket_raised_date, \'DD-MM-YYYY\') ) AS ticket_raised_ts, TO_DATE( TO_CHAR( COALESCE( TRY_TO_TIMESTAMP(spf.ticket_raised_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(spf.ticket_raised_date, \'DD-MM-YYYY\')), \'YYYY-MM-DD\' ),\'YYYY-MM-DD\') AS ticket_raised_date, TRY_TO_DATE(spf.fake_raised_date, \'DD-MM-YYYY\') AS fake_raised_date, DATEDIFF( \'day\', TRY_TO_DATE(r2i.receiving_date, \'DD-MM-YYYY\'),TO_DATE(TO_CHAR( COALESCE( TRY_TO_TIMESTAMP(spf.ticket_raised_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(spf.ticket_raised_date, \'DD-MM-YYYY\')),\'YYYY-MM-DD\' ), \'YYYY-MM-DD\')) AS ageing, spf.TOTAL_QTY, TO_DATE(TO_CHAR(TO_TIMESTAMP_LTZ(TO_NUMBER(spf.last_updated_at) / 1000), \'DD-MM-YYYY\'), \'DD-MM-YYYY\') AS last_updated_at, FROM spf_new_spf_table spf LEFT JOIN return_2_inwarding_data r2i ON spf.TRACKING_NO = r2i.AWB_NO;",
